const promptData = $('Select Prompt').item.json;

return [{
  json: {
    tiktok_caption: promptData.tiktok_caption,
    instagram_caption: promptData.instagram_caption,
    youtube_title: promptData.youtube_title,
    youtube_description: promptData.youtube_description,
    filename: `flowrich_${Date.now()}.mp4`,
    generated_at: new Date().toISOString()
  },
  binary: $input.item.binary
}];

const tiktok = $('Post to TikTok').item.json;
const instagram = $('IG Publish Reel').item.json;
const youtube = $('YT Upload Video').item.json;

return [{
  json: {
    status: 'All platforms posted successfully',
    tiktok: { status: tiktok.data?.publish_id ? 'success' : 'check manually', publish_id: tiktok.data?.publish_id },
    instagram: { status: instagram.id ? 'success' : 'check manually', media_id: instagram.id },
    youtube: { status: youtube.id ? 'success' : 'check manually', video_id: youtube.id },
    posted_at: new Date().toISOString()
  }
}];
